        float normalized_val = gamma * (x_val - mean) * inv_std + beta;
        normalized_val *= *scale;

        sum_exp_d += (double)expf(normalized_val - max_val);
    }

    // Block-wise reduction for sum_exp
    sm_sum_exp[tid] = (float)sum_exp_d;
    __syncthreads();

