        // Apply batch normalization: (val - mean) * inv_std * weight + bias
        val = (val - rm) * inv_std * gw + gb_bn;

        // Add extra bias
        val = val + eb;

        // Divide
        val = val / divide_value;

        // Apply swish activation
        float sig = sigmoid(val);
        output[tid] = val * sig;
    }
