    int total_elements = seq_len * batch_size;
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;
    fused_layer_norm_kernel<<<blocks, threads, 0, stream>>>(input, weight, bias, output, seq_len, batch_size, embed_dim);
}

